"""flange_exact: parametric CadQuery model generated by stl2cad (exact mode, 2.5D).

The part is built along +y from 4 extrusion(s) and 5 cut(s), applied in order;
each is an outline in the xz plane between two levels. Units: mm.
Run:  python flange_exact.py [out.step]
"""

import math
import sys

from cadquery import Edge, Vector
from cadquery import func as cf

# ---- parameters ----------------------------------------------------------
z0 = 0.0    # level along y
z1 = 9.0    # level along y
z2 = 12.0    # level along y
z3 = 25.0    # level along y
z4 = 63.0    # level along y
hole_d1 = 23.3
hole_d2 = 81.0

DIR = (0, 1, 0)


def P(a, b):
    """Point (x, z) in the sketch plane (y = 0)."""
    return (a, 0, b)


def prism(outline, lo, hi):
    """Outline extruded from level lo to level hi."""
    body = cf.extrude(cf.face(outline), [(hi - lo) * c for c in DIR])
    return body.translate(Vector(*[lo * c for c in DIR]))


def hole(a, b, d, lo, hi):
    return prism(Edge.makeCircle(d / 2, P(a, b), DIR), lo, hi)


# ---- 1. extrusion: y 0.0 to 12.0 ------------------------------
outline_1 = cf.wire(
    Edge.makeThreePointArc(P(-17.31, 49.5642), P(0.0, 52.5), P(17.31, 49.5642)),
    cf.segment(P(17.31, 49.5642), P(95.2977, 22.3275)),
    Edge.makeThreePointArc(P(95.2977, 22.3275), P(111.15, 0.0), P(95.2977, -22.3275)),
    cf.segment(P(95.2977, -22.3275), P(17.31, -49.5642)),
    Edge.makeThreePointArc(P(17.31, -49.5642), P(0.0, -52.5), P(-17.31, -49.5642)),
    cf.segment(P(-17.31, -49.5642), P(-95.2977, -22.3275)),
    Edge.makeThreePointArc(P(-95.2977, -22.3275), P(-111.15, 0.0), P(-95.2977, 22.3275)),
    cf.segment(P(-95.2977, 22.3275), P(-17.31, 49.5642)),
)
part = prism(outline_1, z0, z2)

# ---- 2. extrusion: y 12.0 to 63.0 ------------------------------
outline_2 = cf.wire(
    Edge.makeCircle(52.5, P(0.0, 0.0), DIR),
)
part = part + prism(outline_2, z2, z4)

# ---- 3. extrusion: y 12.0 to 25.0 ------------------------------
outline_3 = cf.wire(
    Edge.makeCircle(23.65, P(-87.5, 0.0), DIR),
)
part = part + prism(outline_3, z2, z3)

# ---- 4. extrusion: y 12.0 to 25.0 ------------------------------
outline_4 = cf.wire(
    Edge.makeCircle(23.65, P(87.5, 0.0), DIR),
)
part = part + prism(outline_4, z2, z3)

# ---- round holes: (x, z, diameter, from, to) ------------------------
for a, b, d, lo, hi in [
    (-87.5, 0.0, hole_d1, z0, z3),
    (0.0, 0.0, hole_d2, z0, z4),
    (87.5, 0.0, hole_d1, z0, z3),
]:
    part = part - hole(a, b, d, lo, hi)

# ---- 5. cut: y 9.0 to 12.0 ------------------------------
outline_5 = cf.wire(
    Edge.makeThreePointArc(P(46.342, -30.5468), P(55.5, 0.0), P(46.342, 30.5468)),
    Edge.makeThreePointArc(P(46.342, 30.5468), P(46.3374, 33.8392), P(49.8373, 35.0329)),
    cf.segment(P(49.8373, 35.0329), P(71.7873, 27.3829)),
    Edge.makeThreePointArc(P(71.7873, 27.3829), P(73.7976, 24.6697), P(72.4991, 22.0523)),
    Edge.makeThreePointArc(P(72.4991, 22.0523), P(60.85, 0.0), P(72.4991, -22.0523)),
    Edge.makeThreePointArc(P(72.4991, -22.0523), P(73.7976, -24.6697), P(71.7873, -27.3829)),
    cf.segment(P(71.7873, -27.3829), P(49.8373, -35.0329)),
    Edge.makeThreePointArc(P(49.8373, -35.0329), P(46.3374, -33.8392), P(46.342, -30.5468)),
)
part = part - prism(outline_5, z1, z2)

# ---- 6. cut: y 9.0 to 12.0 ------------------------------
outline_6 = cf.wire(
    Edge.makeThreePointArc(P(-46.342, -30.5468), P(-55.5, 0.0), P(-46.342, 30.5468)),
    Edge.makeThreePointArc(P(-46.342, 30.5468), P(-46.3374, 33.8392), P(-49.8373, 35.0329)),
    cf.segment(P(-49.8373, 35.0329), P(-71.7873, 27.3829)),
    Edge.makeThreePointArc(P(-71.7873, 27.3829), P(-73.7976, 24.6697), P(-72.4991, 22.0523)),
    Edge.makeThreePointArc(P(-72.4991, 22.0523), P(-60.85, 0.0), P(-72.4991, -22.0523)),
    Edge.makeThreePointArc(P(-72.4991, -22.0523), P(-73.7976, -24.6697), P(-71.7873, -27.3829)),
    cf.segment(P(-71.7873, -27.3829), P(-49.8373, -35.0329)),
    Edge.makeThreePointArc(P(-49.8373, -35.0329), P(-46.3374, -33.8392), P(-46.342, -30.5468)),
)
part = part - prism(outline_6, z1, z2)

part = part.clean()

if __name__ == "__main__":
    part.exportStep(sys.argv[1] if len(sys.argv) > 1 else "flange_exact.step")
